using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic by searching the web,
    taking notes on important findings, and then providing a comprehensive summary.

    Follow this process:
    1. Search the web for the given topic using multiple relevant queries.
    2. Take notes on the key findings from each search.
    3. Once you have gathered enough information, provide a final summary of your research.

    Always take notes before summarizing to ensure you capture all important details.
    """)
{
    Tools = [.. AIFunctionFactory.Create(tools)]
};

Console.WriteLine("Research Agent Starting...");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in tools.GetNotes())
{
    Console.WriteLine($"• {note}");
}

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    [AIFunction(Name = "search_web")]
    public Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search - in production, integrate with Bing Search API or similar
        Console.WriteLine($"  [Searching web: \"{query}\"]");
        var results = $"""
            Search results for "{query}":
            1. Overview article discussing key aspects of {query} including recent developments and expert analysis.
            2. Academic paper covering the fundamentals and latest research findings related to {query}.
            3. News report on current trends and future outlook for {query}.
            """;
        return Task.FromResult(results);
    }

    [Description("Save a research note for later reference. Use this to record important findings.")]
    [AIFunction(Name = "take_note")]
    public string TakeNote(
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(content);
        Console.WriteLine($"  [Note taken: {content[..Math.Min(content.Length, 60)]}...]");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
}

