# Check Microsoft.Agents.AI XML
path = os.path.expanduser('~/.nuget/packages/microsoft.agents.ai/')
versions = os.listdir(path)
print('Versions:', versions)
latest = sorted(versions)[-1]
libpath = os.path.join(path, latest, 'lib')
for root, dirs, files in os.walk(libpath):
    for f in files:
        if f.endswith('.xml'):
            print(f'=== {os.path.join(root, f)} ===')
            with open(os.path.join(root, f)) as fh:
                content = fh.read()
            for m in re.finditer(r'<member name=\"[^\"]*ChatClientAgent[^\"]*\">', content):
                start = m.start()
                end = content.find('</member>', start) + len('</member>')
                print(content[start:end][:500])
                print('---')
